--- e7393ea3c:scripts/doc-link-pass.mjs
+++ working:scripts/doc-link-pass.mjs
@@ -0,0 +1,60 @@
+// Semantic guard for the candidate documentation link pass. Pure planning only;
+// callers own writes and retain the returned classification/evidence records.
+import path from 'node:path';
+const posix = path.posix;
+const relation = /source relationship|original source|canonical|legacy (?:source|owner|documents)|current source|source protocol|source document|source of truth|nguồn (?:gốc|chuẩn)/i;
+export function specificTarget(legacy, aliases, candidates, primaryAnchor) {
+  const name = posix.basename(legacy);
+  const same = candidates.filter(p => posix.basename(p) === name && name !== 'README.md');
+  // Preserve the area suffix where restored copies share a filename.
+  const suffix = legacy.replace(/^docs\/architect\//, '');
+  const exact = same.filter(p => p.endsWith(suffix));
+  if (exact.length === 1) return exact[0];
+  if (same.length === 1) return same[0];
+  const restored = same.filter(p => !/\/(?:history|decisions)\//.test(p));
+  if (restored.length === 1) return restored[0];
+  const primary = primaryAnchor && aliases.find(a => a.fromPath === legacy + '#' + primaryAnchor);
+  if (primary && !primary.toOwner.endsWith('/README.md')) return primary.toOwner;
+  const anchored = [...new Set(aliases.filter(a => a.fromPath.startsWith(legacy + '#') && !a.toOwner.endsWith('/README.md')).map(a => a.toOwner))];
+  return anchored.length === 1 ? anchored[0] : null;
+}
+export function planLinkPass({file, text, aliases, candidates, sourceHeadings = {}}) {
+  const edits = [], classified = [], ranges = [];
+  let offset = 0, fence = null, sourceTable = false, inTable = false;
+  for (const line of text.split('\n')) {
+    const mark = /^\s*(`{3,}|~{3,})/.exec(line)?.[1];
+    if (mark) fence = fence && mark[0] === fence[0] && mark.length >= fence.length ? null : fence || mark;
+    const tableRow = line.trim().startsWith('|');
+    if (!tableRow) sourceTable = false;
+    if (tableRow && !inTable && /current source|canonical|original source/i.test(line)) sourceTable = true;
+    inTable = tableRow;
+    ranges.push({start:offset, end:offset+line.length+1, protected:!!fence||!!mark, relation:relation.test(line)||sourceTable});
+    offset += line.length + 1;
+  }
+  const result = text.replace(/\[([^\]]+)\]\(([^\s)]+)\)/g, (whole, label, destination, index) => {
+    const range = ranges.find(r => r.start <= index && index < r.end);
+    if (range.protected || /(^|\/)history\//.test(file) || /^(?:[a-z]+:|#|\/)/i.test(destination)) return whole;
+    const [relative, fragment] = destination.split('#');
+    const legacy = posix.normalize(posix.join(posix.dirname(file), relative));
+    const alias = aliases.find(a => a.fromPath === legacy + (fragment ? '#' + fragment : ''));
+    if (!alias) return whole;
+    let target = alias.toOwner, anchor = alias.toAnchor || null, reason = 'explicit-alias';
+    const record = {file, line:text.slice(0,index).split('\n').length, label, legacy, before:destination};
+    if (range.relation || target === file) {
+      classified.push({...record, reason:range.relation?'provenance/legacy-owner':'self-link', disposition:'retain-legacy-until-cutover'}); return whole;
+    }
+    if (!fragment && target.endsWith('/README.md') && posix.basename(legacy) !== 'README.md') {
+      const specific = specificTarget(legacy, aliases, candidates, sourceHeadings[legacy]);
+      if (!specific && !legacy.startsWith('docs/architect/')) {
+        // A general area spec may intentionally resolve to its area portal.
+      } else if (!specific) {classified.push({...record, reason:'portal-without-specific-target', disposition:'retain-legacy-and-queue'}); return whole;}
+      if (specific) {target = specific; anchor = null; reason = 'specific-candidate';}
+    }
+    if (target === file) {classified.push({...record, reason:'self-link', disposition:'retain-legacy-until-cutover'}); return whole;}
+    let after = posix.relative(posix.dirname(file), target);
+    if (anchor) after += '#' + anchor;
+    edits.push({...record, after, target, anchor, reason});
+    return `[${label}](${after})`;
+  });
+  return {text:result, edits, classified};
+}

--- e7393ea3c:test/scripts/doc-link-pass.test.mjs
+++ working:test/scripts/doc-link-pass.test.mjs
@@ -0,0 +1,70 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { planLinkPass, specificTarget } from '../../scripts/doc-link-pass.mjs';
+const file = 'docs/platform/a/spec.md';
+const aliases = [
+ { fromPath: 'docs/specs/a.md', toOwner: file },
+ { fromPath: 'docs/architect/a/design.md', toOwner: 'docs/platform/a/README.md' },
+ { fromPath: 'docs/architect/a/design.md#details', toOwner: 'docs/platform/a/architecture/design.md', toAnchor: 'details' },
+];
+const candidates = ['docs/platform/a/architecture/design.md'];
+const run = (text, extra = {}) => planLinkPass({ file, text, aliases, candidates, ...extra });
+test('never repoints a source relationship or a link to its own file', () => {
+ for (const text of ['Source relationship: [original source](../../specs/a.md)',
+  'The legacy documents stay canonical: [source](../../specs/a.md)',
+  '[a spec](../../specs/a.md)',
+  '| Source protocol §3 | [design](../../architect/a/design.md) |']) {
+  const r = run(text); assert.equal(r.text, text); assert.equal(r.edits.length, 0); assert.equal(r.classified.length, 1);
+ }
+});
+test('source column header protects subsequent table rows', () => {
+ const text = '| Area | Current source during migration |\n|---|---|\n| A | [design](../../architect/a/design.md) |';
+ assert.equal(run(text).text, text);
+});
+test('chooses a restored same-named candidate before a portal', () => {
+ const r = run('[Design](../../architect/a/design.md)');
+ assert.equal(r.text, '[Design](architecture/design.md)');
+ assert.equal(r.edits[0].reason, 'specific-candidate');
+});
+test('chooses the unique per-anchor target when no same-named candidate exists', () => {
+ assert.equal(specificTarget('docs/architect/a/old.md', [
+  { fromPath: 'docs/architect/a/old.md#one', toOwner: 'docs/platform/a/spec.md', toAnchor: 'one' },
+ ], []), 'docs/platform/a/spec.md');
+});
+test('restores and classifies a portal alias with no specific target', () => {
+ const r = run('[Specific design](../../architect/a/design.md)', { candidates: [], aliases: aliases.slice(0, 2) });
+ assert.equal(r.edits.length, 0); assert.equal(r.classified[0].reason, 'portal-without-specific-target');
+});
+test('wrapped labels are repointed and labels preserved', () => {
+ assert.equal(run('[Dispatch & Execution\nplane](../../architect/a/design.md)').text,
+ '[Dispatch & Execution\nplane](architecture/design.md)');
+});
+test('fences and historical referents are retained', () => {
+ const text = '```md\n[design](../../architect/a/design.md)\n```';
+ assert.equal(run(text).text, text);
+ assert.equal(run('[design](../../architect/a/design.md)', { file: 'docs/platform/a/history/old.md' }).edits.length, 0);
+});
+test('anchored destinations preserve the explicit alias anchor', () => {
+ assert.equal(run('[details](../../architect/a/design.md#details)').text, '[details](architecture/design.md#details)');
+});
+test('ambiguous specific targets fail closed', () => {
+ assert.equal(specificTarget('docs/architect/a/old.md', [
+ {fromPath:'docs/architect/a/old.md#x',toOwner:'docs/platform/a/x.md'},
+ {fromPath:'docs/architect/a/old.md#y',toOwner:'docs/platform/a/y.md'},
+ ], []), null);
+});
+test('uses the source heading alias for a split document without guessing among sections', () => {
+ assert.equal(specificTarget('docs/architect/a/old.md', [
+ {fromPath:'docs/architect/a/old.md#old',toOwner:'docs/platform/a/new.md'},
+ {fromPath:'docs/architect/a/old.md#decision',toOwner:'docs/platform/a/decisions/x.md'},
+ ], [], 'old'), 'docs/platform/a/new.md');
+});
+test('a canonical data cell does not protect unrelated following table rows', () => {
+ const text='| Need | Read |\n|---|---|\n| Canonical source | [a](../../specs/a.md) |\n| Design | [design](../../architect/a/design.md) |';
+ assert.match(run(text).text, /\[design\]\(architecture\/design.md\)/);
+});
+test('restored same-named document takes precedence over an archived heading alias', () => {
+ assert.equal(specificTarget('docs/architect/a/design.md', [
+ {fromPath:'docs/architect/a/design.md#design',toOwner:'docs/platform/a/history/design.md'},
+ ], ['docs/platform/a/architecture/design.md','docs/platform/a/history/design.md'], 'design'), 'docs/platform/a/architecture/design.md');
+});
